    Display the specified number as a badge.

    Args:
        value: The value to be displayed within the badge
        bg_color: Background color CSS name
        show_empty: If true, display the badge even if value is None or zero
    """
def badge(value: Any, bg_color: Any = None, show_empty: Any = False) -> object {
    return {
        'value': value,
        'bg_color': (bg_color or 'secondary'),
        'show_empty': show_empty
    };
}

"""Copies thelist, modifies values to range 0 to 100.

    Designed to handle integer values. Will convert floats.

    :param theList: List of any values of no specified range
    :type theList: list
    :return: List of values with a max. of 100 and min. of 0
    :rtype: list
    :raise ValueError: Supports only numerical values (integers).
    """
def adjustList(theList: Any) -> object {
    adjustedList = [];
    for i in range(len(theList)) {
        if (theList[i] > 100) {
            adjustedList.append(100);
        } elif (theList[i] < 0) {
            adjustedList.append(0);
        } else {
            adjustedList.append(theList[i]);
        }
    }
    return adjustedList;
}

